sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    var empty = "Cannot add empty values!";
	var limit = "Cannot add more than 5 dependents";
	var data = request.body.data;
	var depedentDetails = data.dependentDetails;
	var output = {};
	var resultsForDepedents = [];
	var successCount = 0;
	var failureCount = 0;
	var status = "";

	if(depedentDetails.length == 0){
		gs.info(empty);
		output.validationMessage = empty;
	}
	else if(depedentDetails.length <= 5){

		var depUtil = new x_1806928_health_0.DependentUtil();

		for (var i=0; i< depedentDetails.length; i++){
			var addInfo = depUtil.addDependentInfo(depedentDetails[i]);
			var num = i + 1;
			resultsForDepedents.push("Result for depedent " + depedentDetails[i].name + ": " + addInfo.message);
			if(addInfo.status == "SUCCESS"){
				successCount = successCount + 1;
			}
			else{
				failureCount = failureCount + 1;
			}
			}
		output.depedentAdditionMessage = resultsForDepedents;
		if(successCount > 0 && failureCount == 0){
			status = "SUCCESSFUL";
		}
		else if (successCount > 0 && failureCount > 0){
			status = "PARTIAL SUCCESS";
		}
		else {
			status = "FAILURE";
		}

		}

	else {
		output.validationMessage = limit;
	}

	response.setBody(output);
	if(status == "FAILURE"){
		response.setStatus(400);
	}
	else {
		response.setStatus(200);
	}

})(request, response);
